"""Convierte el transcript .jsonl de Claude Code en un Markdown legible."""
import json
import sys
from pathlib import Path

src = Path(sys.argv[1])
out = Path(sys.argv[2])

TOOL_SUMMARY_KEYS = ("description", "file_path", "command", "url", "action", "query", "pattern")


def summarize_tool(block):
    inp = block.get("input", {}) or {}
    for key in TOOL_SUMMARY_KEYS:
        if key in inp and isinstance(inp[key], str):
            val = inp[key].strip().splitlines()[0][:160]
            return f"`{block.get('name')}` — {val}"
    return f"`{block.get('name')}`"


def user_text(content):
    if isinstance(content, str):
        return content
    parts = [b.get("text", "") for b in content if b.get("type") == "text"]
    return "\n".join(p for p in parts if p)


lines = [f"# Transcript de sesión — {src.stem}\n",
         "Exportado desde Claude Code. Mensajes del usuario y del asistente completos; "
         "las llamadas a herramientas aparecen resumidas en una línea y sus resultados se omiten. "
         "El log crudo está en el `.jsonl` de al lado.\n"]

for raw in src.open(encoding="utf-8"):
    rec = json.loads(raw)
    if rec.get("isMeta") or rec.get("isSidechain"):
        continue
    msg = rec.get("message") or {}
    content = msg.get("content")
    if rec.get("type") == "user":
        if isinstance(content, list) and all(b.get("type") == "tool_result" for b in content):
            continue
        text = user_text(content).strip()
        if not text or text.startswith("<system-reminder>") and "\n" not in text:
            continue
        # quita recordatorios de sistema incrustados
        while "<system-reminder>" in text:
            a = text.find("<system-reminder>")
            b = text.find("</system-reminder>", a)
            if b == -1:
                break
            text = (text[:a] + text[b + len("</system-reminder>"):]).strip()
        if text:
            lines.append(f"\n---\n\n## 🧑 Usuario\n\n{text}\n")
    elif rec.get("type") == "assistant" and isinstance(content, list):
        for b in content:
            if b.get("type") == "text" and b.get("text", "").strip():
                lines.append(f"\n### 🤖 Asistente\n\n{b['text'].strip()}\n")
            elif b.get("type") == "tool_use":
                lines.append(f"\n> 🔧 {summarize_tool(b)}\n")

out.write_text("\n".join(lines), encoding="utf-8")
print(f"ok: {out} ({out.stat().st_size} bytes)")

